patch:
diff --git a/packages/runtime-core/src/componentSlots.ts b/packages/runtime-core/src/componentSlots.ts
index 6114f6c..285f1e1 100644
--- a/packages/runtime-core/src/componentSlots.ts
+++ b/packages/runtime-core/src/componentSlots.ts
@@ -180,7 +180,7 @@ const assignSlots = (
     // when rendering the optimized slots by manually written render function,
     // do not copy the `slots._` compiler flag so that `renderSlot` creates
     // slot Fragment with BAIL patchFlag to force full updates
-    if (optimized || !isInternalKey(key)) {
+    if (optimized || (key !== '_' && key !== '__')) {
       slots[key] = children[key]
     }
   }
diff --git a/packages/vue/__tests__/index.spec.ts b/packages/vue/__tests__/index.spec.ts
index 0c969f1..1cf1ed7 100644
--- a/packages/vue/__tests__/index.spec.ts
+++ b/packages/vue/__tests__/index.spec.ts
@@ -311,4 +311,32 @@ describe('compiler + runtime integration', () => {
     app.mount(root)
     expect(root.innerHTML).toBe('<div>60000000100000111</div>')
   })
+
+  // #13611
+  test('should render slots whose names start with an underscore', async () => {
+    const show = ref(false)
+    const BaseLayout = {
+      template: `<div><slot name="header" /><slot /></div>`,
+    }
+    const SubComponent = {
+      template: `<p><slot name="_slot1">default1</slot>|<slot name="_slot2">default2</slot></p>`,
+    }
+    const root = document.createElement('div')
+    createApp({
+      components: { BaseLayout, SubComponent },
+      setup: () => ({ show }),
+      template: `
+        <BaseLayout>
+          <template v-if="show" #header>header</template>
+          <SubComponent>
+            <template #_slot2>custom2</template>
+          </SubComponent>
+        </BaseLayout>`,
+    }).mount(root)
+    expect(root.innerHTML).toBe('<div><p>default1|custom2</p></div>')
+
+    show.value = true
+    await nextTick()
+    expect(root.innerHTML).toBe('<div>header<p>default1|custom2</p></div>')
+  })
 })
